-- Generated reproducible draft seed from the TWO provided CSV files.
-- Read and apply 202611250001 + 202611250002 migrations first.
-- This script does NOT publish prices. It refuses to replace a published batch.
-- Original input rows are also retained at data/grocery/*.csv.
begin;
do $seed$
declare v_batch uuid;v_status text;v_prices integer;v_stores integer;
begin
 insert into public.grocery_csv_batches(snapshot_date,status)
 values ('2026-11-25'::date,'draft') on conflict(snapshot_date) do nothing;
 select id,status into v_batch,v_status from public.grocery_csv_batches
 where snapshot_date='2026-11-25'::date for update;
 if v_status='published' then
   raise exception 'Refusing to overwrite a published seed batch';
 end if;
 delete from public.wpb_grocery_prices where batch_id=v_batch;
 delete from public.wpb_grocery_stores where batch_id=v_batch;
 insert into public.wpb_grocery_stores(
 batch_id,id,chain,flyer_id,store_number,address,city,state,zip,phone,hours_mon_sat,hours_sun,palm_beach_county)
 select v_batch,x.* from jsonb_to_recordset($stores_json$
